import numpy as np,sys
f=sys.argv[1]
L=open(f).read().split('\n'); n=int(L[0]); sym=[];xyz=[]
for l in L[2:2+n]:
    p=l.split(); sym.append(p[0]); xyz.append([float(x) for x in p[1:4]])
xyz=np.array(xyz)
r={'H':0.35,'C':0.77,'N':0.72,'P':1.10,'Cl':1.02,'Ru':1.35}
D=np.linalg.norm(xyz[:,None]-xyz[None],axis=-1)
adj=[[] for _ in range(n)]
for i in range(n):
    for j in range(i+1,n):
        if D[i,j]<1.25*(r[sym[i]]+r[sym[j]]): adj[i].append(j); adj[j].append(i)
expect={0:6,1:1,2:1,3:3,52:4,104:3}
bad=[]
for i in range(n):
    nb=len(adj[i])
    if sym[i]=='H' and nb!=1: bad.append((i,sym[i],nb,[ (j,sym[j]) for j in adj[i]]))
    elif sym[i]=='C' and nb!=(4 if i not in (3,104) else 3): 
        if not (i in (3,104) and nb==3): bad.append((i,sym[i],nb))
    elif sym[i]=='N' and nb!=3: bad.append((i,sym[i],nb))
    elif i in expect and nb!=expect[i]: bad.append((i,sym[i],nb))
print('bad:',bad)
def d(i,j): return round(float(D[i,j]),3)
def ang(i,j,k):
    a=xyz[i]-xyz[j]; b=xyz[k]-xyz[j]
    return round(float(np.degrees(np.arccos(a@b/np.linalg.norm(a)/np.linalg.norm(b)))),1)
print('Ru-Cl',d(0,1),d(0,2),'Ru-CNHC',d(0,3),'Ru-P',d(0,52),'Ru=C',d(0,104))
print('CNHC-Ru-P',ang(3,0,52),'Cl-Ru-Cl',ang(1,0,2),'C=Ru-CNHC',ang(104,0,3),'C=Ru-P',ang(104,0,52))
